"""Load a trusted local artifact and apply the validation-selected threshold."""

from pathlib import Path

import joblib
import numpy as np

from ticket_router.data import combine_text


class TicketRouter:
    def __init__(self, pipeline, threshold: float):
        if not np.isfinite(threshold) or not 0 <= threshold <= 1:
            raise ValueError("Routing threshold must be between zero and one")
        self.pipeline = pipeline
        self.threshold = float(threshold)

    @classmethod
    def load(cls, path: Path):
        # Joblib uses pickle. Only load artifacts generated by trusted training code.
        artifact = joblib.load(path)
        if artifact.get("schema_version") != 1:
            raise ValueError("Unsupported model artifact schema")
        return cls(artifact["pipeline"], artifact["threshold"])

    def predict(self, subject: str, description: str) -> dict:
        text = combine_text(subject, description)
        probabilities = self.pipeline.predict_proba([text])[0]
        index = int(np.argmax(probabilities))
        confidence = float(probabilities[index])
        category = str(self.pipeline.classes_[index])
        # A threshold of 1.0 explicitly disables automatic routing.
        automatic = self.threshold < 1.0 and confidence >= self.threshold
        return {
            "predicted_category": category,
            "confidence": confidence,
            "routing_decision": "auto_route" if automatic else "manual_review",
            "assigned_team": category if automatic else None,
        }
